def nrm(a: np.ndarray) -> float:
    return float(np.sqrt(ddot(a.ravel(), a.ravel())))

def neumann_1d(a: np.ndarray, axis: int, scale: float) -> np.ndarray:
    """scale * tridiag(-1,[1,2,...,2,1],-1), applied along one mode."""
    v = np.moveaxis(a, axis, 0)
    differences = v[1:] - v[:-1]
    out = np.empty_like(v)
    out[0] = -differences[0]
    out[-1] = differences[-1]
    out[1:-1] = differences[:-1] - differences[1:]
    return np.moveaxis(scale * out, 0, axis)

def apply_full(x: np.ndarray, scale: float) -> np.ndarray:
    """Independent physical-space stencil, for diagnostics/reference only."""
    return sum((neumann_1d(x, axis, scale) for axis in range(3)))

def encode(x):
    if isinstance(x, torch.Tensor):
        return as_numpy(x).tolist()
    if isinstance(x, np.generic):
        return x.item()
    if isinstance(x, Path):
        return str(x)
    raise TypeError(type(x).__name__)

def dump(path, obj):
    Path(path).write_text(json.dumps(obj, indent=2, ensure_ascii=False, default=encode), encoding='utf-8')

def storage_metrics(basis, n):
    latest = basis[-1]
    total = sum((v.storage for v in basis))
    q = len(basis)
    return dict(last_basis_rank_1=latest.ranks[0], last_basis_rank_2=latest.ranks[1], last_basis_max_rank=max(latest.ranks), last_basis_tt_entries=latest.storage, active_basis_count=q, active_basis_tt_entries=total, last_basis_storage_ratio=latest.storage / n ** 3, active_basis_storage_ratio=total / (q * n ** 3))

def _json_default(value):
    if isinstance(value, torch.Tensor):
        return as_numpy(value).tolist()
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, np.generic):
        return value.item()
    if isinstance(value, np.ndarray):
        return value.tolist()
    raise TypeError(f'无法保存 JSON 类型：{type(value).__name__}')

def write_json(path, value):
    """原子替换，避免写到一半的元数据文件被误当成完整文件。"""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + '.tmp')
    tmp.write_text(json.dumps(value, ensure_ascii=False, indent=2, default=_json_default), encoding='utf-8')
    tmp.replace(path)

def _read_json(path):
    return json.loads(Path(path).read_text(encoding='utf-8'))

def load_json(path):
    return _read_json(path)

def _run_id():
    return datetime.now().strftime('%Y%m%d_%H%M%S_%f') + '_' + uuid.uuid4().hex[:6]

class NotebookTee:

    def __init__(self, *streams):
        self.streams = streams

    def write(self, text):
        for stream in self.streams:
            stream.write(text)
            stream.flush()
        return len(text)

    def flush(self):
        for stream in self.streams:
            stream.flush()

def latest_run(key):
    """返回该模块最近一组数据已完整保存的目录，不把中断的数据当作完成。"""
    pointer = Path(OUTPUT_ROOT).resolve() / key / 'latest_complete.json'
    if not pointer.exists():
        raise FileNotFoundError(f'{key} 尚无完成的数据。先 mode="run"，或在 source 中指定已有运行目录。')
    relative = _read_json(pointer)['run_id']
    folder = pointer.parent / relative
    if not folder.is_dir():
        raise FileNotFoundError(f'已记录的运行目录不存在：{folder}')
    return folder

def _resolve_run(key, source):
    root = latest_run(key) if source is None else Path(source).expanduser().resolve()
    if root.name == 'results' and (root.parent / 'manifest.json').exists():
        root = root.parent
    manifest_file = root / 'manifest.json'
    if not manifest_file.exists():
        raise FileNotFoundError(f'{root} 不是本模板保存的运行目录（缺少 manifest.json）。请指定含 results/ 和 manifest.json 的目录。')
    manifest = _read_json(manifest_file)
    if manifest.get('data_status') != 'complete':
        raise RuntimeError('所选数据未完整结束。已保存的 history.csv 可以人工核验，但不能冒充完整实验。')
    return (root, manifest)

def _checked_parameters(module, overrides):
    overrides = {} if overrides is None else dict(overrides)
    unknown = set(overrides) - set(module.defaults)
    if unknown:
        raise ValueError(f'模块 {module.key} 没有这些实验参数：{sorted(unknown)}；请检查拼写。')
    params = copy.deepcopy(module.defaults)
    params.update(copy.deepcopy(overrides))
    return params

def _render_saved(module, run_dir, manifest, style):
    if manifest['schema'] != module.schema:
        raise ValueError(f"数据类型 {manifest['schema']} 与模块所需 {module.schema} 不兼容。")
    figure_dir = run_dir / 'figures' / module.key / _run_id()
    figure_dir.mkdir(parents=True, exist_ok=False)
    draw_record = {'module': module.key, 'title': module.title, 'module_version': module.version, 'data_source': str(run_dir), 'source_parameters': manifest['parameters'], 'style': style, 'created_at': datetime.now().isoformat(), 'status': 'drawing'}
    write_json(figure_dir / 'render.json', draw_record)
    try:
        artifacts = module.draw(run_dir / 'results', figure_dir, copy.deepcopy(style))
        if not isinstance(artifacts, dict) or not artifacts:
            raise ValueError('draw 必须返回非空字典，例如 {"png": Path(...), "pdf": Path(...)}。')
        artifacts = {name: Path(path).resolve() for (name, path) in artifacts.items()}
        for path in artifacts.values():
            if not path.is_file():
                raise FileNotFoundError(f'绘图函数没有创建声明的文件：{path}')
        draw_record['status'] = 'complete'
        draw_record['files'] = {name: path.name for (name, path) in artifacts.items()}
        write_json(figure_dir / 'render.json', draw_record)
        return (figure_dir, artifacts)
    except BaseException as exc:
        draw_record.update(status='failed', error=repr(exc))
        write_json(figure_dir / 'render.json', draw_record)
        raise

def run_figure(key, *, mode='run', params=None, source=None, style=None, show=True):
    """统一入口。

    run     只运行指定模块的实验，然后画图；到达步数上限也正常出图。
    plot    只读取已保存数据，绝不调用 compute；不能借重画修改实验阈值。
    prepare 只显示模块与参数，不计算。

    新模块可以使用 source=latest_run('figure3') 共享已保存的兼容数据。
    """
    if key not in FIGURE_MODULES:
        raise KeyError(f'尚未注册 {key}。先运行该模块的代码单元格。已注册：{list(FIGURE_MODULES)}')
    if mode not in {'run', 'plot', 'prepare'}:
        raise ValueError('mode 只能是 "run"、"plot"、"prepare"。')
    module = FIGURE_MODULES[key]
    draw_style = dict(dpi=320, linewidth=0.7, marker_points=24, display_width=1100)
    if style:
        draw_style.update(copy.deepcopy(style))
    if not 50 <= int(draw_style['dpi']) <= 1200:
        raise ValueError('dpi 应为 50 至 1200。')
    if float(draw_style['linewidth']) <= 0 or int(draw_style['marker_points']) < 2:
        raise ValueError('linewidth 必须为正数，marker_points 至少为2。')
    if mode == 'prepare':
        print(f'当前图：{module.title}  [ID: {key}]')
        print(json.dumps(_checked_parameters(module, params), ensure_ascii=False, indent=2))
        print('仅加载完毕，尚未运行。把 MODE 改为 "run" 后重新运行控制台单元格。')
        return None
    if mode == 'plot':
        if params:
            raise ValueError('重画不能修改实验参数。只传 style；修改 epsilon/delta 等需要 mode="run"。')
        (run_dir, manifest) = _resolve_run(key, source)
        print('读取已保存的数据，不重跑求解器：', run_dir)
    else:
        if source is not None:
            raise ValueError('mode="run" 不读取 source。仅重画旧数据请使用 mode="plot"。')
        parameters = _checked_parameters(module, params)
        run_dir = Path(OUTPUT_ROOT).expanduser().resolve() / key / _run_id()
        results_dir = run_dir / 'results'
        results_dir.mkdir(parents=True, exist_ok=False)
        manifest = {'module': key, 'title': module.title, 'module_version': module.version, 'framework_version': FRAMEWORK_VERSION, 'schema': module.schema, 'parameters': parameters, 'created_at': datetime.now().isoformat(), 'data_status': 'running', 'plot_status': 'not_started', 'engine_source_sha256_at_template_build': ENGINE_SOURCE_SHA256, 'software': dict(python=sys.version, numpy=np.__version__, scipy=scipy.__version__, pandas=pd.__version__, platform=platform.platform())}
        manifest['pytorch_runtime'] = runtime_metadata()
        write_json(run_dir / 'manifest.json', manifest)
        write_json(run_dir.parent / 'latest_attempt.json', {'run_id': run_dir.name})
        print(f'运行模块：{key} — {module.title}\n保存目录：{run_dir}')
        with (run_dir / 'run.log').open('w', encoding='utf-8') as log:
            with contextlib.redirect_stdout(NotebookTee(sys.stdout, log)), contextlib.redirect_stderr(NotebookTee(sys.stderr, log)):
                try:
                    module.compute(copy.deepcopy(parameters), results_dir)
                except BaseException as exc:
                    manifest['data_status'] = 'interrupted' if isinstance(exc, KeyboardInterrupt) else 'memory_error' if isinstance(exc, MemoryError) else 'failed'
                    manifest['error'] = repr(exc)
                    manifest['ended_at'] = datetime.now().isoformat()
                    write_json(run_dir / 'manifest.json', manifest)
                    print('本次运行未完整结束；已写入的逐步记录保留在：', results_dir)
                    raise
                manifest['data_status'] = 'complete'
                manifest['ended_at'] = datetime.now().isoformat()
                write_json(run_dir / 'manifest.json', manifest)
                write_json(run_dir.parent / 'latest_complete.json', {'run_id': run_dir.name})
    try:
        (figure_dir, artifacts) = _render_saved(module, run_dir, manifest, draw_style)
    except BaseException:
        if mode == 'run':
            manifest['plot_status'] = 'failed_data_preserved'
            write_json(run_dir / 'manifest.json', manifest)
        print('计算数据仍保留。修正绘图后可 mode="plot" 重画，无需重新计算。')
        raise
    if mode == 'run':
        manifest['plot_status'] = 'complete'
        write_json(run_dir / 'manifest.json', manifest)
    answer = FigureResult(key, run_dir, run_dir / 'results', figure_dir, artifacts, mode)
    print('图已保存：', figure_dir)
    if show:
        show_result(answer, width=int(draw_style['display_width']))
    return answer

def show_result(result, width=1100):
    if result is None:
        return
    summary_file = result.results_dir / 'summary.csv'
    if summary_file.exists():
        frame = pd.read_csv(summary_file)
        names = {'n': '每维n', 'completed_corrections': '实际修正次数', 'total_Arnoldi_extensions': 'Arnoldi扩展次数', 'status': '停止状态', 'final_eta1': '最终变换后向误差', 'final_transformed_relative_residual': '最终相对变换残差', 'final_forward_error': '最终Drazin相对解误差'}
        available = [name for name in names if name in frame]
        display(frame[available].rename(columns=names))
    if 'png' in result.artifacts:
        display(DisplayImage(filename=str(result.artifacts['png']), width=width))

