def math_number(value):
    value = float(value)
    if value <= 0 or not np.isfinite(value):
        raise ValueError('数值必须为有限正数。')
    exponent = int(np.floor(np.log10(value)))
    factor = value / 10.0 ** exponent
    return f'10^{{{exponent}}}' if np.isclose(factor, 1.0) else f'{factor:g}\\times10^{{{exponent}}}'

def load_grid_data(results_dir):
    """只读 CSV/JSON；不推测或补造未运行的数据。"""
    results_dir = Path(results_dir)
    cfg = _read_json(results_dir / 'configuration.json')
    grids = [int(n) for n in cfg['n']]
    if not grids:
        raise ValueError('配置中没有网格。')
    data = {}
    summaries = []
    for n in grids:
        folder = results_dir / f'n{n}'
        if not (folder / 'history.csv').exists() or not (folder / 'summary.json').exists():
            raise FileNotFoundError(f'n={n} 缺少已完成运行的 history.csv 或 summary.json。')
        df = pd.read_csv(folder / 'history.csv')
        if df.empty or not df['n'].eq(n).all() or df['iteration'].iloc[0] != 0:
            raise ValueError(f'n={n} 的轨迹格式不正确。')
        if (df['iteration'].diff().dropna() < 0).any():
            raise ValueError('累计修正次数不能倒退；重启可有重复横坐标。')
        checks = [np.allclose(df['last_basis_storage_ratio'], df['last_basis_tt_entries'] / n ** 3), np.allclose(df['active_basis_storage_ratio'], df['active_basis_tt_entries'] / (df['active_basis_count'] * n ** 3)), np.array_equal(df['solution_max_rank'], df[['x_rank_1', 'x_rank_2']].max(axis=1))]
        if not all(checks):
            raise ValueError(f'n={n} 的秩/存储指标核验失败。')
        data[n] = df
        summaries.append(_read_json(folder / 'summary.json'))
    meta = {}
    for field_name in ('epsilon', 'delta', 'max_corrections', 'restart_correction_dimension', 'stop_on_tolerance'):
        values = [s[field_name] for s in summaries]
        if any((v != values[0] for v in values[1:])):
            raise ValueError(f'网格间 {field_name} 不一致，不能使用统一图注。')
        meta[field_name] = values[0]
    meta['n'] = grids
    return (data, meta)

def figure4_validate_parameters(parameters):
    """检查一组配对实验的公共参数。"""
    for (key, minimum) in (('n_mode', 3), ('restart', 1), ('max_corrections', 1), ('cp_rank', 1), ('threads', 1)):
        value = parameters[key]
        if isinstance(value, bool) or int(value) != value or int(value) < minimum:
            raise ValueError(f'{key} 必须是至少为 {minimum} 的整数。')
    orders = parameters['orders']
    if not isinstance(orders, (list, tuple)) or not orders:
        raise ValueError('orders 需要是非空列表，例如 [4, 5, 6]。')
    if any((isinstance(d, bool) or int(d) != d or int(d) < 2 for d in orders)):
        raise ValueError('orders 中的每个张量阶数必须是至少为 2 的整数。')
    if len(set(orders)) != len(orders):
        raise ValueError('orders 不能包含重复的阶数。')
    for key in ('delta', 'epsilon', 'null_ratio'):
        if not np.isfinite(float(parameters[key])):
            raise ValueError(f'{key} 必须是有限数。')
    if not 0 <= float(parameters['delta']) < 1 or float(parameters['epsilon']) <= 0:
        raise ValueError('要求 0 <= delta < 1 且 epsilon > 0。')
    if float(parameters['null_ratio']) < 0:
        raise ValueError('null_ratio 不能小于 0。')
    if int(parameters['max_mode']) != parameters['max_mode'] or int(parameters['max_mode']) < 1:
        raise ValueError('max_mode 必须是正整数。')
    if parameters.get('use_preconditioner', False):
        raise NotImplementedError('Figure 4 当前比较同一未预条件算子。')
    if not isinstance(parameters['stop_on_tolerance'], (bool, np.bool_)):
        raise ValueError('stop_on_tolerance 必须是 True 或 False。')

def figure4_load_data(results_dir):
    """只读取纯 TT 配对实验；旧稠密缓存版本不能混入。"""
    root = Path(results_dir)
    cfg = load_json(root / 'configuration.json')
    figure4_validate_parameters(cfg)
    protocol = load_json(root / 'protocol.json')
    if protocol.get('tt_backend') != 'pytorch_core_qr_svd_mgs1_v1':
        raise ValueError('这组数据不是纯 TT 核版本；请保留旧图并为新版单独计算数据。')
    data = {}
    required = ['iteration', 'arnoldi_steps', 'elapsed_seconds', 'eta_DGMRES_transformed', 'active_basis_count', 'basis_representation_bytes', 'basis_dense_cache_bytes', 'basis_total_bytes', 'method', 'd', 'n_mode']
    for d in map(int, cfg['orders']):
        for method in ('dgmres', 'tt_dgmres'):
            folder = root / f'd{d}' / method
            frame = pd.read_csv(folder / 'history.csv')
            summary = load_json(folder / 'summary.json')
            if frame.empty or set(required) - set(frame.columns):
                raise ValueError(f'd={d}, {method} 的历史数据不完整。')
            if not frame['method'].eq(method).all() or not frame['d'].eq(d).all():
                raise ValueError('轨迹中的方法或阶数标签与目录不一致。')
            if not frame['n_mode'].eq(int(cfg['n_mode'])).all():
                raise ValueError('轨迹中的 mode 大小与配置不一致。')
            if float(frame['iteration'].iloc[0]) != 0:
                raise ValueError('轨迹需要包含零初值。')
            for column in ('iteration', 'arnoldi_steps', 'elapsed_seconds'):
                if (frame[column].diff().dropna() < 0).any():
                    raise ValueError(f'{column} 不应倒退。')
            metrics = frame[[name for name in required if name not in ('method',)]].to_numpy(float)
            if not np.isfinite(metrics).all() or (metrics < 0).any():
                raise ValueError('曲线含非有限或负指标；请核对原始运行状态。')
            if not np.allclose(frame['basis_total_bytes'], frame['basis_representation_bytes'] + frame['basis_dense_cache_bytes'], rtol=0, atol=0):
                raise ValueError('基存储量分项与总量不一致。')
            expected_dense = frame['active_basis_count'] * int(cfg['n_mode']) ** d * 8
            if method == 'dgmres':
                correct_storage = np.array_equal(frame['basis_representation_bytes'], expected_dense) and frame['basis_dense_cache_bytes'].eq(0).all()
            else:
                correct_storage = frame['basis_dense_cache_bytes'].eq(0).all()
            if not correct_storage:
                raise ValueError('基存储统计不符合纯 TT 核/全向量分支约定。')
            if summary.get('method') != method or int(summary['d']) != d:
                raise ValueError('汇总文件与历史方法标签不一致。')
            if summary.get('orthogonalization') != 'MGS1':
                raise ValueError('Figure 4 的两种方法必须采用相同的单次 MGS。')
            if not np.isclose(float(summary['final_eta1']), float(frame['eta_DGMRES_transformed'].iloc[-1]), rtol=1e-12, atol=0):
                raise ValueError('最终后向误差与末行历史记录不一致。')
            data[d, method] = frame
    return (data, cfg)

@register_figure
def figure4_comparison_module():
    PARAMETERS = {'n_mode': 12, 'orders': [4, 5, 6], 'delta': 1e-05, 'epsilon': 1e-07, 'restart': 25, 'max_corrections': 300, 'stop_on_tolerance': True, 'seed': 20260906, 'max_mode': 11, 'cp_rank': 3, 'null_ratio': 0.1, 'threads': 1, 'verbose': True, 'use_preconditioner': False}

    def compute(parameters, results_dir):
        figure4_validate_parameters(parameters)
        root = Path(results_dir)
        root.mkdir(parents=True, exist_ok=True)
        write_json(root / 'configuration.json', parameters)
        protocol = {'operator': 'same symmetric scaled Neumann Kronecker sum; index=1', 'initial_guess': 'zero', 'orthogonalization': 'MGS1 for both methods', 'backward_error': '||A(b-Ax)||_2 / (||x||_2 + ||Ab||_2); ||A^2||_2=1', 'timing': 'initialization + solver + independent diagnostics in each representation; excludes shared problem construction, file I/O and plotting', 'storage': 'live Krylov-basis array payload; TT cores versus full vectors; no dense TT basis cache; not process RSS or peak workspace', 'separate_storage_fields': ['basis_representation_bytes', 'basis_dense_cache_bytes'], 'tt_backend': 'pytorch_core_qr_svd_mgs1_v1', 'tt_implementation': 'TT-core matvec, MGS1, QR/SVD rounding and residual checks; no full-vector expansion', 'arithmetic': 'PyTorch float64 TT cores; NumPy/SciPy CPU projected solves and dense baseline', 'source_sha256_at_template_build': FIGURE4_SOURCE_SHA256}
        protocol.update(runtime_metadata())
        protocol['tt_backend'] = 'pytorch_core_qr_svd_mgs1_v1'
        write_json(root / 'protocol.json', protocol)
        (summaries, histories) = ([], [])
        with threadpool_limits(limits=int(parameters['threads'])):
            write_json(root / 'environment.json', {'python': sys.version, 'numpy': np.__version__, 'scipy': scipy.__version__, 'platform': platform.platform(), 'threadpools': threadpool_info(), 'pytorch_runtime': runtime_metadata()})
            for (position, d) in enumerate(map(int, parameters['orders'])):
                folder = root / f'd{d}'
                folder.mkdir(parents=True, exist_ok=True)
                problem = make_problem_nd(n_mode=int(parameters['n_mode']), d=d, seed=int(parameters['seed']), max_mode=int(parameters['max_mode']), cp_rank=int(parameters['cp_rank']), null_ratio=float(parameters['null_ratio']))
                write_json(folder / 'problem.json', problem['metadata'])
                methods = ('dgmres', 'tt_dgmres') if position % 2 == 0 else ('tt_dgmres', 'dgmres')
                for method in methods:
                    gc.collect()
                    print(f"Figure 4: N={parameters['n_mode']}^{d}, {method}", flush=True)
                    result = figure4_solve(problem, method=method, delta=float(parameters['delta']), epsilon=float(parameters['epsilon']), restart=int(parameters['restart']), max_corrections=int(parameters['max_corrections']), stop_on_tolerance=bool(parameters['stop_on_tolerance']), out=folder / method, verbose=bool(parameters['verbose']))
                    rows = [dict(row, method=method, d=d, n_mode=int(parameters['n_mode'])) for row in result['history']]
                    summary = dict(result['summary'], method=method, d=d, n_mode=int(parameters['n_mode']), orthogonalization='MGS1')
