                    pd.DataFrame(summaries).to_csv(root / 'summary.csv', index=False)
                    pd.DataFrame(histories).to_csv(root / 'all_histories.csv', index=False)
                    write_json(root / 'summaries.json', summaries)
                    del result
                del problem
        figure4_load_data(root)

    def draw(results_dir, figure_dir, style):
