        specs = [('a', 'elapsed_seconds', 'Time (s)', '(a) Cumulative computation time', 1.0), ('b', 'eta_DGMRES_transformed', '$\\eta_1(x_k)$', '(b) Transformed backward error', 1.0), ('c', 'basis_total_bytes', 'Basis storage (MiB)', '(c) Stored Krylov basis\nTT cores vs full vectors', 1.0 / 2 ** 20)]
        (panel_w, panel_h) = (3.55, 3.65)
